CREATE TYPE "workspace_role" AS ENUM ('owner','admin','member','viewer');
CREATE TYPE "membership_state" AS ENUM ('active','suspended','removed');
CREATE TYPE "ticket_type" AS ENUM ('bug','feature','task','improvement');
CREATE TYPE "ticket_priority" AS ENUM ('p1','p2','p3','p4');
CREATE TABLE "workspaces" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(100) NOT NULL, "slug" varchar(63) NOT NULL UNIQUE, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(100) NOT NULL, "email" varchar(320) NOT NULL UNIQUE, "avatar_url" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "workspace_memberships" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id"), "user_id" uuid NOT NULL REFERENCES "users"("id"), "role" workspace_role NOT NULL, "state" membership_state NOT NULL DEFAULT 'active', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("workspace_id","user_id"), UNIQUE("workspace_id","id"));
CREATE TABLE "projects" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id"), "name" varchar(100) NOT NULL, "slug" varchar(80) NOT NULL, "key" varchar(10) NOT NULL CHECK ("key" ~ '^[A-Z][A-Z0-9]{1,9}$'), "description" text NOT NULL DEFAULT '', "archived_at" timestamptz, "version" integer NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("workspace_id","key"), UNIQUE("workspace_id","slug"), UNIQUE("workspace_id","id"));
CREATE TABLE "workflow_statuses" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id"), "name" varchar(50) NOT NULL, "key" varchar(30) NOT NULL, "position" integer NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("workspace_id","key"), UNIQUE("workspace_id","id"));
CREATE TABLE "ticket_sequences" ("project_id" uuid PRIMARY KEY REFERENCES "projects"("id"), "workspace_id" uuid NOT NULL, "current_value" integer NOT NULL DEFAULT 0, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "tickets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id"), "project_id" uuid NOT NULL REFERENCES "projects"("id"), "sequence_number" integer NOT NULL, "identifier" varchar(30) NOT NULL, "title" varchar(200) NOT NULL, "description" text NOT NULL DEFAULT '', "type" ticket_type NOT NULL, "priority" ticket_priority NOT NULL, "status_id" uuid NOT NULL REFERENCES "workflow_statuses"("id"), "reporter_membership_id" uuid NOT NULL REFERENCES "workspace_memberships"("id"), "assignee_membership_id" uuid REFERENCES "workspace_memberships"("id"), "position" integer NOT NULL DEFAULT 1000, "blocked" boolean NOT NULL DEFAULT false, "due_date" date, "version" integer NOT NULL DEFAULT 1, "archived_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("project_id","sequence_number"), UNIQUE("workspace_id","identifier"), UNIQUE("workspace_id","id"));
CREATE INDEX "tickets_board_idx" ON "tickets"("workspace_id","status_id","position");
CREATE TABLE "labels" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id"), "name" varchar(50) NOT NULL, "color" varchar(30) NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("workspace_id","name"), UNIQUE("workspace_id","id"));
CREATE TABLE "ticket_labels" ("workspace_id" uuid NOT NULL, "ticket_id" uuid NOT NULL REFERENCES "tickets"("id") ON DELETE CASCADE, "label_id" uuid NOT NULL REFERENCES "labels"("id") ON DELETE CASCADE, PRIMARY KEY("ticket_id","label_id"));
CREATE TABLE "activity_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "workspace_id" uuid NOT NULL REFERENCES "workspaces"("id"), "project_id" uuid NOT NULL REFERENCES "projects"("id"), "ticket_id" uuid REFERENCES "tickets"("id"), "actor_membership_id" uuid NOT NULL REFERENCES "workspace_memberships"("id"), "action" varchar(100) NOT NULL, "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb, "correlation_id" varchar(100), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "activity_ticket_idx" ON "activity_events"("workspace_id","ticket_id","created_at");
CREATE OR REPLACE FUNCTION prevent_activity_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'activity events are append-only'; END $$;
CREATE TRIGGER activity_events_append_only BEFORE UPDATE OR DELETE ON "activity_events" FOR EACH ROW EXECUTE FUNCTION prevent_activity_mutation();
